//! #7260: a program whose first stage builds the whole document (an assignment or `del`) reads
//! a lone regular file straight into that tree a chunk at a time, and `--slurpfile` reads its file the
//! same way, so neither run holds the file's text (nor, for the first, its semi-index) beside the
//! tree. Whatever the one-pass reader declines (a repeated key, `nan`, a byte-order mark, a second
//! document, a fault, nesting past its limit, an empty file) is read again by the route that always
//! read it. These rows pin both sides against jq: the outputs, the exit codes, and the line a runtime
//! error names, which the reader now works out from where the value completes (a line of exactly one
//! of jq's 4095-byte reads, white space after the value, a scalar's trailing newline). Every expected
//! text was captured from jq 1.7.1 (`/usr/bin/jq`); `{f}` stands for the file's path.

use anyhow::Result;

use crate::run_jq_full;

/// The documents the rows below read, by name.
fn document(name: &str) -> String {
    let long = |n: usize| "x".repeat(n);
    match name {
        "compact" => r#"{"a":1,"b":[1,2,{"c":"x"}],"f":1.50,"big":100000000000000000001}"#.into(),
        "compact_nl" => "{\"a\":1,\"b\":[1,2]}\n".into(),
        "pretty" => "{\n  \"a\": 1,\n  \"b\": [\n    1\n  ]\n}\n\n  \n".into(),
        "lead_ws" => "\n\n   {\"a\":1}\n".into(),
        "trail_ws" => "{\"a\":1}   \t  ".into(),
        "scalar_nl" => "12\n".into(),
        "scalar_nonl" => "12".into(),
        "scalar_str" => "\"s\"\n".into(),
        "line4094" => format!("{{\"a\":\"{}\"}}\n", long(4087)),
        "line4095" => format!("{{\"a\":\"{}\"}}\n", long(4088)),
        "line4096" => format!("{{\"a\":\"{}\"}}\n", long(4089)),
        "line4095_ws" => format!("{{\"a\":\"{}\"}}  \n", long(4088)),
        "nl_then_long" => format!("\n\n{{\"a\":\"{}\"}}{}\n\n", long(4088), " ".repeat(7)),
        "dup" => r#"{"a":1,"a":2}"#.into(),
        "nan" => r#"{"a":nan}"#.into(),
        "bom" => "\u{feff}{\"a\":1}\n".into(),
        "two" => "{\"a\":1}\n{\"a\":2}\n".into(),
        "trunc" => r#"{"a":[1,2"#.into(),
        "garbage" => r#"{"a":1} x"#.into(),
        "deep" => format!("{{\"a\":{}{}}}", "[".repeat(200), "]".repeat(200)),
        "empty" => String::new(),
        "users" => {
            let users: Vec<String> = (0..300)
                .map(|i| format!(r#"{{"id":{i},"name":"U{i}","age":{}}}"#, i % 50))
                .collect();
            format!(r#"{{"users":[{}]}}"#, users.join(","))
        }
        other => unreachable!("no document {other}"),
    }
}

/// One row: `(document, flags, program, stdout, stderr, exit code)`.
type Case = (
    &'static str,
    &'static [&'static str],
    &'static str,
    &'static str,
    &'static str,
    i32,
);

