#[test]
fn test_programs_that_build_the_document_first_match_jq_7260() -> Result<()> {
    let dir = tempfile::tempdir()?;
    let mut failures = Vec::new();
    for &(name, flags, program, stdout, stderr, code) in &CASES {
        let path = dir.path().join(format!("{name}.json"));
        std::fs::write(&path, document(name))?;
        let file = path.to_str().expect("a UTF-8 temporary path");
        let mut args: Vec<&str> = flags.to_vec();
        args.extend([program, file]);
        let got = run_jq_full(&args, None)?;
        let want = (
            stdout.replace("{f}", file),
            stderr.replace("{f}", file),
            code,
        );
        if got != want {
            failures.push(format!(
                "{name} {flags:?} {program:?}: got {got:?}, want {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    Ok(())
}

#[test]
fn test_slurpfile_read_in_chunks_matches_jq_7260() -> Result<()> {
    let dir = tempfile::tempdir()?;
    let mut failures = Vec::new();
    for &(name, program, stdout) in &SLURP_CASES {
        let path = dir.path().join(format!("{name}.json"));
        std::fs::write(&path, document(name))?;
        let file = path.to_str().expect("a UTF-8 temporary path");
        let got = run_jq_full(&["-c", "-n", "--slurpfile", "d", file, program], None)?;
        if got != (stdout.to_string(), String::new(), 0) {
            failures.push(format!("{name} {program:?}: got {got:?}, want {stdout:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    // A file the reader declines is read again by the route that reports it: jq's wording up to
    // the detail after the colon, and its exit code.
    for name in ["trunc", "garbage"] {
        let path = dir.path().join(format!("{name}.json"));
        std::fs::write(&path, document(name))?;
        let file = path.to_str().expect("a UTF-8 temporary path");
        let (out, err, code) = run_jq_full(&["-n", "--slurpfile", "d", file, "$d"], None)?;
        assert_eq!((out.as_str(), code), ("", 2), "{name}");
        assert!(
            err.starts_with(&format!("jq: Bad JSON in --slurpfile d {file}: ")),
            "{name}: {err}"
        );
    }
    Ok(())
}
